import { describe, expect, it } from 'vitest';
import { summarizeAct } from '../game/play/actSummary';
import { ACTS } from '.';

/*
 * This test is the generator for actSummaries.generated.ts. A file snapshot compares the
 * file with what the content summarizes to today; `npm run content:summaries` runs it with
 * --update, which rewrites the file instead. CI never writes snapshots, so a summary left
 * stale by a content change fails CI, and the message names the command that fixes it.
 */

/**
 * The most the generated file may hold. The real summaries are well under it; a step,
 * card or drill body copied in by mistake would blow far past it.
 */
const MAX_CHARACTERS = 40_000;

/** The generated module's source: a header, then every shipped Act's summary as JSON. */
function summariesSource(): string {
  const summaries = ACTS.map((content) => summarizeAct(content));
  return [
    '// Generated by src/content/actSummaries.test.ts from every Act in src/content.',
    "// Don't edit it by hand: after changing an Act, run `npm run content:summaries`.",
    "import type { ActSummary } from '../game/play/actSummary';",
    '',
    `export const ACT_SUMMARIES: readonly ActSummary[] = ${JSON.stringify(summaries, null, 2)};`,
    '',
  ].join('\n');
}

const SOURCE = summariesSource();

describe('the generated Act summaries', () => {
  it('match the content in src/content', async () => {
    await expect(SOURCE).toMatchFileSnapshot(
      './actSummaries.generated.ts',
      'Act content changed: run npm run content:summaries',
    );
  });

  it('stay small, so no step, card or drill body leaks into the first download', () => {
    expect(SOURCE.length).toBeLessThan(MAX_CHARACTERS);
  });
});
